      {#if ['stone_piece','surface'].includes(kind)}<label>{kind==='surface'?'Flächenart':'Bauteilart'}<select use:searchableSelect={purpose} bind:value={purpose} onchange={()=>{if(kind==='stone_piece')purposeChanged();}} onfocus={()=>{if(kind==='surface'&&!['floor','wall','ceiling','shower','inscription'].includes(purpose))purpose='floor';if(kind==='stone_piece'&&snapshot.kind==='memorial'&&purpose==='countertop')purpose='memorial';}}>{#each kind==='surface'?[['floor','Boden'],['wall','Wand'],['ceiling','Decke'],['shower','Dusche'],['inscription','Beschriftungsfläche']]:[['memorial','Grabmal / Stele'],...(snapshot.kind==='memorial'?[['base','Sockel']]:[]),['countertop','Waschtisch- / Arbeitsplatte'],['floor','Bodenplatte'],['wall','Wandplatte'],['sill','Fensterbank'],['step','Stufe / Podest'],['other','Anderes Bauteil']] as option}<option value={option[0]}>{option[1]}</option>{/each}</select></label>{/if}
      {#if targetMissing}<div class="prerequisite-note"><strong>{kind==='opening'?'Eine Öffnung braucht eine Wand.':kind==='inscription'?'Ihre Inschrift braucht eine Fläche.':'Diese Bearbeitung braucht ein Bauteil.'}</strong><p>{kind==='opening'?'Legen Sie zuerst die passende Wand mit ihren Maßen an. Danach setzen Sie die Öffnung hier fort.':'Legen Sie zuerst den Stein mit Form und Maßen an. Ihre Eingaben hier bleiben währenddessen erhalten.'}</p>{#if onprerequisite}<button type="button" class="btn" onclick={requestPrerequisite}>{kind==='opening'?'Zuerst Wand anlegen':'Zuerst Stein anlegen'}</button>{/if}</div>{/if}
      {#if kind==='inscription'||kind==='machining'||kind==='slope'}<label>{kind==='inscription'?'Beschriftungsfläche':'Bezugsbauteil'}<select use:searchableSelect={host} data-dependent-target bind:value={host} required disabled={targetMissing} aria-describedby={targets.length>1?'add-target-hint':undefined}><option value="">{targets.length>1?'Passendes Bauteil wählen':'Bitte wählen'}</option>{#each targets as item}<option value={item.id}>{item.label}</option>{/each}</select></label>{#if targets.length>1}<p class="explanation" id="add-target-hint">{host?'Dieses Element wird dem gewählten Bauteil zugeordnet.':'Mehrere Bauteile passen. Wählen Sie bewusst, auf welchem Sie arbeiten möchten.'}</p>{/if}{/if}
      {#if kind==='machining'}<label>Bearbeitungsart<select use:searchableSelect={machiningType} bind:value={machiningType} onchange={()=>{label=machiningNames[machiningType];if(machiningType==='drip_edge')machiningFace='back';}}>{#each Object.entries(machiningNames) as [key,name]}<option value={key}>{name}</option>{/each}</select></label>{#if machiningType!=='cutout'}<label>Bearbeitungsseite<select use:searchableSelect={machiningFace} bind:value={machiningFace}><option value="front">Vorderseite / lokale Oberfläche</option><option value="back">Rückseite / Unterseite</option></select></label>{/if}{#if machiningType==='miter'}<label>Gerade Bauteilkante<select use:searchableSelect={miterEdge} bind:value={miterEdge}>{#if machiningHost?.kind==='stone_piece'}{#each machiningHost.finishedContour.outer as edge,index}<option value={String(index)}>Kante {index+1} · {edge.from.xMm} / {edge.from.yMm} bis {edge.to.xMm} / {edge.to.yMm}</option>{/each}{/if}</select></label><label>Gehrungswinkel zur Fläche (Grad)<input bind:value={miterAngle} inputmode="decimal" placeholder="Ausdrücklich festlegen" required/></label><p class="explanation">Parametrischer gerader Gehrungskeil an einem rechteckigen Einzelbauteil. Breite folgt aus der tatsächlichen Stärke und dem Winkel, auf 0,01 mm quantisiert. Freiform-Gehrungen benötigen eine eigene geprüfte Fertigungskontur.</p>{:else if machiningType!=='cutout'}<label class="check"><input type="checkbox" bind:checked={through}/>Ausdrücklich durch die volle Materialstärke</label>{#if !through}<label>Bearbeitungstiefe ({units.unit})<LengthInput bind:value={cutDepth} inputmode="decimal" placeholder="Unbekannt bleibt offen"/></label>{/if}{/if}<p class="explanation">Lage und Kontur beziehen sich auf die lokale Fläche des gewählten Steins. Bohrungen erhalten hier keine automatische Befestigungsfreigabe.</p>{/if}
      {#if kind==='stone_piece'&&purpose==='memorial'}<details class="shape-options" bind:open={shapePickerOpen}><summary><span>Grundform</span><strong>{memorialShapes.find(entry=>entry.id===shape)?.label??'Rechteck'}</strong><span class="shape-change">Ändern</span></summary><ShapePicker bind:value={shape} onchange={()=>{shapePickerOpen=false;void tick().then(()=>dialog.querySelector<HTMLInputElement>('[data-width-input]')?.focus());}}/></details>{#if shape==='rounded'}<label>Eckenradius ({units.unit})<LengthInput bind:value={radius} inputmode="decimal" placeholder="12 % der kürzeren Seite"/></label>{/if}{#if shape==='segment_arch'}<label>Bogenhöhe ({units.unit})<LengthInput bind:value={archRise} inputmode="decimal" placeholder="18 % der Breite"/></label>{/if}<p class="explanation">Jede Grundform bleibt anschließend frei bearbeitbar. Eigene Konturen können Sie als SVG oder DXF importieren.</p>{/if}
      {#if kind==='inscription'}<label>Wörtlicher Text / Namen und Daten<textarea bind:value={text} rows="5" required placeholder="Originalschreibweise und Zeilenfolge"></textarea></label><p class="explanation">Namen, Daten und Zeichen wie * oder † bleiben genau so erhalten, wie Sie sie eingeben.</p><label for="add-design-font">Entwurfsschrift</label><select use:searchableSelect={previewFontKey} id="add-design-font" bind:value={previewFontKey}>{#each planningFonts as entry}<option value={entry.key}>{entry.label}</option>{/each}</select><label>Schriftfarbe<input type="color" bind:value={previewColor}/></label><fieldset class="placement-presets"><legend>Lage auf dem Stein</legend><div class="preset-buttons">{#each inscriptionPresets as [key,name]}<button type="button" aria-pressed={placement===key} onclick={()=>placement=key}>{name}</button>{/each}</div><p class="explanation">{placement==='custom'?'Eigene Abstände unter „Position auf dem Stein“.':`Waagerecht mittig; ${placement==='top'?'oben mit Randabstand':placement==='upper_third'?'Textmitte auf zwei Dritteln der Steinhöhe':'senkrecht mittig'}${presetUV?` · ${Math.round(Number(presetUV.uMm))} mm von links, ${Math.round(Number(presetUV.vMm))} mm von unten`:''}.`} Danach lässt sich die Schrift direkt auf dem Stein ziehen.</p></fieldset><details class="supplier-details"><summary>Herstellerschrift und Bestellangaben</summary><label>Herstellerschrift<select use:searchableSelect={font} bind:value={font}><option value="">Später festlegen · {fonts.length} Bildreferenzen</option>{#each fonts as entry}<option value={entry.version_id??entry.id}>{entry.name} · {entry.selection_ref} · {entry.supply_form==='wording'?'Schriftzug':'Einzelbuchstaben'}</option>{/each}</select></label><p class="explanation">Originale Herstellerbildreferenz; Zeichenkonturen und Befestigungspunkte sind damit nicht verifiziert. Der Text bleibt unverändert.</p><p class="explanation">Diese Angaben betreffen die Schrift. Das Natursteinmaterial ändern Sie am Trägerstein{host?` „${targets.find(target=>target.id===host)?.label??''}“`:''}.</p><label>Herstellerartikel der Schrift<input bind:value={article} placeholder="Artikelnummer der Schriftausführung · optional"/></label><label for={`${dialogId}-inscription-material`}>Materialstand der Schrift · optional</label><ReferencePicker id={`${dialogId}-inscription-material`} reference="material-versions" initial={materials} value={material} onchange={value=>material=value}/></details>{/if}
      {#if kind==='catalog_object'}<label for="add-product-version">Eingefrorene Produktvariante</label><ProductPicker id="add-product-version" initial={products} value={product} onchange={chooseProduct}/>{#if productBusy}<p class="explanation" role="status">Eingefrorene Produktmaße werden geladen …</p>{/if}{#if !product}<p class="explanation">Ein freies Hüllmodell ist als Annäherung gekennzeichnet und erzeugt keinen erfundenen bestellbaren Artikel.</p>{/if}{/if}
      {#if kind==='grave_border'}<p class="explanation">Rechteckige Einfassung mit Stumpfstößen: zwei durchgehende Quersteine und zwei dazwischenliegende Längssteine. Vier einzelne Bauteile erscheinen in Zeichnung, 3D und Stückliste. Die Stoßfuge ist ausdrücklich festzulegen; Fundament und Befestigung erhalten einen eigenen offenen Prüfpunkt.</p>{/if}
      {#if kind==='room'}<label>Raumgrenze anlegen<select use:searchableSelect={roomMode} bind:value={roomMode}><option value="rectangle">Neues Rechteck mit vier Wänden</option><option value="walls">Vorhandene Wände gemeinsam nutzen</option></select></label>{#if roomMode==='walls'}<BoundaryFields {snapshot} bind:boundary={roomBoundary}/>{/if}{/if}
      {#if kind==='wall'}<label>Anfangsknoten<select use:searchableSelect={startNode} bind:value={startNode}><option value="">Neuer Knoten aus Position X / Y / Z</option>{#each snapshot.elements.filter(e=>e.kind==='node') as node}<option value={node.id}>{node.label}</option>{/each}</select></label><label>Endknoten<select use:searchableSelect={endNode} bind:value={endNode}><option value="">Neuer Knoten aus X-/Y-Versatz</option>{#each snapshot.elements.filter(e=>e.kind==='node') as node}<option value={node.id}>{node.label}</option>{/each}</select></label><p class="explanation">Vorhandene Knoten werden direkt gemeinsam referenziert. Für einen neuen Endpunkt sind auch null oder negative X-/Y-Versätze zulässig, solange die Wand eine echte Länge hat.</p>{/if}
      {#if kind==='room'&&roomMode==='rectangle'}<fieldset class="measure-basis"><legend>Worauf beziehen sich Ihre Raummaße?</legend><label class="basis-choice"><input type="radio" name={`${dialogId}-measure-basis`} value="clear" bind:group={roomMeasureBasis}/><span>Lichte Innenmaße<small>Zwischen den Innenseiten der Wandkerne, ohne Belag.</small></span></label><label class="basis-choice"><input type="radio" name={`${dialogId}-measure-basis`} value="axis" bind:group={roomMeasureBasis}/><span>Wandachsmaße<small>Von Wandmitte zu Wandmitte, z. B. aus einem Bauplan.</small></span></label></fieldset>{/if}
      {#if kind==='room'&&roomMode==='rectangle'||kind==='wall'}<details class="placement-options"><summary>Wandanschlüsse im Detail</summary><label>Geometrischer Kernanschluss<select use:searchableSelect={joinStyle} bind:value={joinStyle}><option value="miter">Geometrische Gehrung an gemeinsamen Knoten</option><option value="legacy_overlap">Überlappung am Achsknoten</option></select></label><p class="explanation">Gemeinsame Knoten verbinden die Wandkörper. Schräge Anschlussflächen sind geometrisch berechnet; eine fachliche Montage-, Statik- oder Abdichtungsfreigabe wird dadurch nicht erteilt.</p></details>{/if}
      {#if kind==='opening'}<label>Bezugswand<select use:searchableSelect={wall} data-dependent-target bind:value={wall} required disabled={targetMissing} aria-describedby={targets.length>1?'add-wall-hint':undefined}><option value="">Wand wählen</option>{#each targets as e}<option value={e.id}>{e.label}</option>{/each}</select></label>{#if targets.length>1}<p class="explanation" id="add-wall-hint">{wall?'Die Öffnung liegt in der ausgewählten Wand.':'Wählen Sie die Wand, in der Tür, Fenster oder Nische liegen soll.'}</p>{/if}<OpeningWallPreview {snapshot} wallId={wall} offsetMm={x} widthMm={width}/><label>Öffnungstyp<select use:searchableSelect={openingType} bind:value={openingType}><option value="door">Tür</option><option value="window">Fenster</option><option value="recess">Nische</option><option value="passage">Durchgang</option></select></label>{/if}
      {#if kind==='opening'&&openingType==='recess'}<label>Nischentiefe ab Kernoberfläche ({units.unit})<LengthInput bind:value={cutDepth} inputmode="decimal" placeholder="Unbekannt bleibt offen"/></label><label>Seite des Wandkerns<select use:searchableSelect={recessSide} bind:value={recessSide}><option value="left">Links in Wandrichtung</option><option value="right">Rechts in Wandrichtung</option></select></label><p class="explanation">Die Tiefe wird ab der Kernoberfläche gemessen. Zugeordnete Schichten auf der gewählten Seite werden ebenfalls ausgespart. Die gegenüberliegende Wandfläche bleibt erhalten.</p>{/if}
      <div class="form-grid">
        {#if ['room','stone_piece','wall','opening','surface','catalog_object','clearance','machining','grave_border','slope','connection'].includes(kind)&&!product&&!(kind==='machining'&&machiningType==='miter')&&!(kind==='room'&&roomMode==='walls')&&!(kind==='wall'&&endNode)}<label>{kind==='connection'||kind==='machining'&&machiningType==='borehole'?'Durchmesser':kind==='slope'?'Lauflänge':kind==='wall'?'X-Versatz des Endpunkts':kind==='room'?(roomMeasureBasis==='clear'?'Lichte Raumbreite':'Achsbreite'):kind==='opening'?'Öffnungsbreite':kind==='stone_piece'&&!upright?'Länge':'Breite'} ({units.unit})<LengthInput data-width-input bind:value={width} inputmode="decimal" required={['room','stone_piece','wall','surface','catalog_object','clearance','machining','grave_border','slope'].includes(kind)}/></label>{/if}
        {#if ['room','wall','surface','catalog_object','clearance','machining','grave_border'].includes(kind)&&!product&&!(kind==='machining'&&['borehole','miter'].includes(machiningType))&&!(kind==='room'&&roomMode==='walls')&&!(kind==='wall'&&endNode)}<label>{kind==='wall'?'Y-Versatz des Endpunkts':kind==='room'?(roomMeasureBasis==='clear'?'Lichte Raumtiefe':'Achstiefe'):'Tiefe'} ({units.unit})<LengthInput bind:value={depth} inputmode="decimal" required/></label>{/if}
        {#if ['room','stone_piece','inscription','opening','wall','catalog_object','clearance','grave_border','slope'].includes(kind)&&!product&&!(kind==='room'&&roomMode==='walls')}<label>{kind==='inscription'?'Gewünschte Zeichenhöhe':kind==='slope'?'Höhenunterschied':kind==='room'?'Raumhöhe':kind==='wall'?'Wandhöhe':kind==='opening'?'Öffnungshöhe':kind==='stone_piece'&&!upright?(purpose==='wall'?'Höhe':'Tiefe'):'Höhe'} ({units.unit})<LengthInput bind:value={height} inputmode="decimal" required={kind==='stone_piece'||kind==='room'&&roomMode==='rectangle'}/></label>{/if}
        {#if ['room','stone_piece','wall','surface','machining','grave_border'].includes(kind)&&!(kind==='room'&&roomMode==='walls')}<label>{kind==='room'||kind==='wall'?'Wandstärke ohne Belag':kind==='machining'?'Erforderlicher Mindestreststeg':kind==='grave_border'?'Randbreite':kind==='stone_piece'&&purpose==='base'?'Tiefe':'Materialstärke'} ({units.unit})<LengthInput bind:value={thickness} inputmode="decimal" placeholder={kind==='room'&&roomMeasureBasis==='clear'?'Erforderlich für lichte Innenmaße':'Unbekannt bleibt offen'} required={kind==='room'&&roomMode==='rectangle'&&roomMeasureBasis==='clear'}/></label>{/if}
        {#if kind==='inscription'}<label>Maximale Schriftbreite ({units.unit})<LengthInput bind:value={maxWidth} inputmode="decimal" placeholder="Verbindliches Platzlimit"/></label><label>Zeilenabstand ({units.unit})<LengthInput bind:value={gap} inputmode="decimal" placeholder="Offen"/></label>{/if}
        {#if kind==='surface'}<label>Fugenbreite ({units.unit})<LengthInput bind:value={gap} inputmode="decimal" placeholder="Offen"/></label>{/if}
        {#if kind==='grave_border'}<label>Ausdrücklich gewählte Stoßfuge ({units.unit})<LengthInput bind:value={gap} inputmode="decimal" placeholder="Auch null ausdrücklich eingeben" required/></label>{/if}
      </div>
      {#if memorialPiece&&stackOptions.length}{@const partner=stackOptions.find(e=>e.id===stackPartner)}<fieldset class="stack-option"><legend class="sr-only">Lage auf dem Sockel</legend><label class="stack-check"><input type="checkbox" bind:checked={stackEnabled}/><span>Stein mittig auf Sockel stellen<small>{purpose==='base'?`Der Sockel kommt mittig unter „${partner?.label??'den Stein'}“; der Stein steht auf der Sockeloberkante.`:`Der Stein steht mittig auf „${partner?.label??'dem Sockel'}“.`} Ändert sich der Sockel, bleibt der Stein darauf stehen.</small></span></label>{#if stackEnabled&&stackOptions.length>1}<label>{purpose==='base'?'Stein auf diesem Sockel':'Sockel'}<select bind:value={stackPartner}>{#each stackOptions as option}<option value={option.id}>{option.label}</option>{/each}</select></label>{/if}</fieldset>{/if}
      {#if ['stone_piece','surface','grave_border','room'].includes(kind)}<label for={`${dialogId}-material-version`}>{kind==='room'?'Bodenbelag · optional':'Naturstein / Material · optional'}</label>{#if kind==='room'}<p class="explanation">Das gewählte Material wird dem Boden dieses Raums zugeordnet. Wandbeläge und Schichtstärken legen Sie separat fest.</p>{/if}<MaterialPicker id={`${dialogId}-material-version`} materials={data.related?.materials??[]} value={material} onchange={value=>material=value}/>{/if}
      {#if kind==='opening'&&openingType==='door'}<div class="form-grid"><label>Bandseite<select use:searchableSelect={hinge} bind:value={hinge}><option value="left">Links</option><option value="right">Rechts</option></select></label><label>Öffnungsrichtung<select use:searchableSelect={direction} bind:value={direction}><option value="inward">Nach innen</option><option value="outward">Nach außen</option><option value="sliding">Schiebend</option><option value="none">Keine</option></select></label></div>{/if}
      {#if kind==='connection'||kind==='clearance'}<label>Fachlicher Bezug<select use:searchableSelect={host} bind:value={host}><option value="">Eigenständiger Bezug</option>{#each snapshot.elements.filter(e=>['stone_piece','surface','catalog_object','wall'].includes(e.kind)) as item}<option value={item.id}>{item.label}</option>{/each}</select></label><p class="explanation">Der fachliche Bezug benennt das betroffene Bauteil. Die Positionswerte beziehen sich weiterhin auf das angezeigte Koordinatensystem.</p>{/if}
      {#if kind==='connection'}<label>Anschlussart<select use:searchableSelect={connectionType} bind:value={connectionType}><option value="water">Wasser</option><option value="waste">Abfluss</option><option value="electric">Elektro</option><option value="fastening">Befestigung</option><option value="joint">Fuge / Anschluss</option><option value="other">Andere</option></select></label>{/if}
      {#if kind==='technical_note'}<label>Hinweistext<textarea bind:value={text} rows="4" required></textarea></label><label>Kategorie<select use:searchableSelect={category} bind:value={category}><option value="information">Information</option><option value="approval_required">Fachfreigabe erforderlich</option><option value="installation">Montagehinweis</option><option value="source">Quelle / Regel</option></select></label>{/if}
      <details class="placement-options" open={['opening','machining','wall','node','connection'].includes(kind)}><summary>{kind==='opening'?'Lage in der Wand':kind==='machining'?'Lage der Bearbeitung':kind==='inscription'?'Position auf dem Stein · optional':'Position im Plan · optional'}</summary><p class="explanation" id={`${dialogId}-placement-help`}>{kind==='opening'?'Messen Sie ab dem vorhandenen Wandanfang A in Pfeilrichtung zu B. A liegt auf der Wandachse und ist nicht automatisch die innere Raumecke.':kind==='room'&&roomMeasureBasis==='clear'?'Bezugspunkt ist die linke untere Innenecke des Wandkerns.':kind==='inscription'?'Abstand von links bis zur Textmitte, Abstand von unten bis zur Grundlinie der letzten Zeile. Angezeigt auf 1 mm gerundet.':'Startposition 0 / 0. Sie können das Element anschließend im Plan verschieben.'}</p>
      {#if !(kind==='machining'&&machiningType==='miter')}<div class="form-grid">{#if !(kind==='room'&&roomMode==='walls')&&!(kind==='wall'&&startNode)}<label>{kind==='inscription'?'Abstand von links':kind==='opening'?'Abstand längs der Wand':kind==='machining'&&machiningType==='borehole'?'Bohrmittelpunkt X':'Position X'} ({units.unit})<LengthInput bind:value={x} roundMm={kind==='inscription'} oninput={()=>{if(kind==='inscription')placement='custom';}} inputmode="decimal" aria-describedby={kind==='opening'||kind==='inscription'?`${dialogId}-placement-help`:undefined} required/></label>{/if}{#if !['inscription','opening'].includes(kind)&&!(kind==='room'&&roomMode==='walls')&&!(kind==='wall'&&startNode)}<label>{kind==='machining'&&machiningType==='borehole'?'Bohrmittelpunkt Y':'Position Y'} ({units.unit})<LengthInput bind:value={y} inputmode="decimal" required/></label>{/if}{#if kind!=='machining'&&!(kind==='wall'&&startNode)}<label>{kind==='room'&&roomMode==='walls'?'Oberkante Fertigfußboden':kind==='inscription'?'Abstand von unten':kind==='opening'?'Brüstungshöhe':'Position Z / Höhenbezug'} ({units.unit})<LengthInput bind:value={z} roundMm={kind==='inscription'} oninput={()=>{if(kind==='inscription')placement='custom';}} aria-describedby={kind==='inscription'?`${dialogId}-placement-help`:undefined} inputmode="decimal" required/></label>{/if}</div>{/if}
      </details>
      <details class="placement-options"><summary>Bestand, Rückbau & Gruppierung</summary><div class="form-grid"><label>Planungsphase<select use:searchableSelect={phase} bind:value={phase}><option value="planned">Geplant</option><option value="existing">Bestand</option><option value="demolition">Rückbau</option></select></label><label>Gruppe<select use:searchableSelect={parent} bind:value={parent}><option value="">Keine Gruppe</option>{#each snapshot.elements.filter(e=>e.kind==='group') as g}<option value={g.id}>{g.label}</option>{/each}</select></label></div>
      </details>
      {#if error}<p class="form-error" role="alert">{error}</p>{/if}
    </div>
    {#if ['stone_piece','room','inscription'].includes(kind)}
      <aside class="draft-preview-pane"><DraftElementPreview {kind} {width} {height} {depth} {thickness} shape={purpose==='base'?'rectangle':shape} {radius} {archRise} {text} {gap} {maxWidth} u={x} v={z} fontKey={previewFontKey} color={previewColor} hostId={host} {snapshot} purpose={kind==='stone_piece'?purpose:''} material={previewMaterial}/></aside>
    {/if}</div><footer><button type="button" class="btn" onclick={onclose}>Abbrechen</button><button type="submit" class="btn primary" disabled={productBusy||targetMissing}>In den Plan übernehmen</button></footer>
  </form>
</dialog>
<style>
  dialog{box-sizing:border-box;padding:0;border:1px solid var(--glass-border,var(--line));border-radius:24px;max-width:650px;width:calc(100% - 32px);max-height:90dvh;box-shadow:var(--overlay-shadow);color:var(--ink);background:var(--paper)}
  dialog.with-preview{max-width:940px}
  form{display:flex;flex-direction:column;max-height:calc(90dvh - 2px)}
  .dialog-layout{display:grid;grid-template-columns:minmax(0,1fr);min-height:0;flex:1;overflow:hidden}
  .with-preview .dialog-layout{grid-template-columns:minmax(0,1.35fr) minmax(260px,1fr)}
  .draft-preview-pane{min-height:0;overflow:auto;border-left:1px solid var(--line-soft);background:var(--input-surface)}
  @keyframes studio-dialog-enter{from{opacity:0;transform:translateY(10px) scale(.99)}to{opacity:1;transform:translateY(0) scale(1)}}dialog[open]{animation:studio-dialog-enter .24s cubic-bezier(.2,.8,.2,1)}
  header,footer{padding:22px 26px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);gap:14px}header h2{font-size:20px;line-height:1.4;letter-spacing:-.025em;margin:0}footer{border:0;border-top:1px solid var(--line);justify-content:flex-end;gap:10px;flex-wrap:wrap}.close{background:none;border:0;font-size:28px;color:var(--muted);cursor:pointer;min-width:44px;min-height:44px;flex:none}
  .dialog-body{padding:8px 26px 24px;overflow:auto;max-height:calc(90dvh - 170px)}label{display:block;font-size:13px;font-weight:600;margin-top:17px}input:not([type=checkbox],[type=radio],[type=color]),textarea,select{display:block;box-sizing:border-box;width:100%;font:inherit;font-size:14px;font-weight:400;color:var(--ink);background:var(--input-surface,var(--paper));border:1px solid var(--line);border-radius:8px;padding:10px 11px;min-height:42px;margin-top:7px}textarea{line-height:1.6;resize:vertical}input:not([type=checkbox],[type=radio]):focus,textarea:focus,select:focus{outline:2px solid var(--forest);outline-offset:2px}input[type=color]{display:block;box-sizing:border-box;width:64px;height:44px;padding:5px;margin-top:7px;border:1px solid var(--line);border-radius:8px;background:var(--paper);cursor:pointer}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.explanation{font-size:12px;line-height:1.7;color:var(--muted);font-weight:400}.form-error{color:var(--danger);background:var(--danger-wash);padding:12px;font-size:13px;white-space:pre-wrap;border-radius:8px}
